ALTER TABLE "automation_executions"
  ADD COLUMN IF NOT EXISTS "workflow" jsonb NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN IF NOT EXISTS "context" jsonb NOT NULL DEFAULT '{}'::jsonb,
  ADD COLUMN IF NOT EXISTS "cursor" integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS "resume_at" timestamp with time zone,
  ADD COLUMN IF NOT EXISTS "waiting_approval_task_id" integer,
  ADD COLUMN IF NOT EXISTS "updated_at" timestamp with time zone NOT NULL DEFAULT now();

ALTER TABLE "automation_executions"
  ALTER COLUMN "result" SET DEFAULT '[]'::jsonb;

CREATE INDEX IF NOT EXISTS "automation_executions_resume_idx"
  ON "automation_executions" ("status", "resume_at");

CREATE INDEX IF NOT EXISTS "automation_executions_approval_idx"
  ON "automation_executions" ("waiting_approval_task_id");

-- Role/job-profile demand across WFM coverage, open shifts, and scenarios
ALTER TABLE "staffing_requirements"
  ADD COLUMN IF NOT EXISTS "job_profile_id" integer REFERENCES "job_profiles"("id") ON DELETE restrict;

DROP INDEX IF EXISTS "staffing_requirement_unique";
CREATE UNIQUE INDEX IF NOT EXISTS "staffing_requirement_role_unique"
  ON "staffing_requirements" (
    "organization_id",
    "worksite_id",
    "work_date",
    "shift_definition_id",
    COALESCE("job_profile_id", 0)
  );
CREATE INDEX IF NOT EXISTS "staffing_requirement_role_idx"
  ON "staffing_requirements" ("organization_id", "job_profile_id", "work_date");

ALTER TABLE "open_shifts"
  ADD COLUMN IF NOT EXISTS "job_profile_id" integer REFERENCES "job_profiles"("id") ON DELETE restrict;

CREATE INDEX IF NOT EXISTS "open_shifts_role_idx"
  ON "open_shifts" ("organization_id", "job_profile_id", "work_date", "status");

-- Explicit dated allow/deny decisions for HCM worksite eligibility.
-- Existing rows remain allows for backward compatibility.
ALTER TABLE "hcm_worksite_authorizations"
  ADD COLUMN IF NOT EXISTS "decision" varchar(8) NOT NULL DEFAULT 'allow';

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'hcm_worksite_authorization_decision_check'
  ) THEN
    ALTER TABLE "hcm_worksite_authorizations"
      ADD CONSTRAINT "hcm_worksite_authorization_decision_check"
      CHECK ("decision" IN ('allow','deny'));
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS "hcm_worksite_authorizations_decision_idx"
  ON "hcm_worksite_authorizations" ("organization_id","employee_id","worksite_id","decision","effective_from");
